import {clone,uid,MATERIALS,formatMeasure,validateProject} from './core.js';
import {createRoom,CATALOG,createRoomObject,footprint,findPlacement,placementIssues,roomScene,validateRoomCopy} from './room-core.js';

const $=s=>document.querySelector(s);
const mini={bed:'<path d="M3 17V8h18v9M3 12h18M6 8V5h12v3M5 17v3m14-3v3M6 10h4m4 0h4"/>',desk:'<path d="M2 8h20v3H2zM4 11v10m16-10v10M4 17h16"/>',wardrobe:'<path d="M4 3h16v18H4zM12 3v18m-3-12v4m6-4v4"/>',chair:'<path d="M6 12V3h12v9M4 12h16v4H4zM6 16v5m12-5v5"/>',piece:'<path d="m3 8 9-5 9 5v9l-9 5-9-5V8Zm0 0 9 5 9-5m-9 5v9"/>'};
const drawingIcon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${mini[k]||mini.piece}</svg>`;

export class RoomEditor{
 constructor(c){this.c=c;this.lastActive=null;this.setupDOM();}
 get p(){return this.c.getProject();}get data(){return this.p.room;}get active(){return Boolean(this.data?.active);}get objects(){return this.data?.objects||[];}get selected(){return this.objects.find(o=>o.id===this.c.getSelected());}
 m(v){return formatMeasure(v,this.p.unit||'cm');}
 setupDOM(){
  $('#planning-modes').addEventListener('click',e=>{const b=e.target.closest('[data-plan-mode]');if(b)this.activate(b.dataset.planMode==='room');});
  $('#room-tools').addEventListener('click',e=>{if(e.target.closest('[data-room-add]'))this.catalog();if(e.target.closest('[data-room-settings]'))this.settings();if(e.target.closest('[data-room-rotate]'))this.rotateSelected();});
  $('#room-sidebar').addEventListener('click',e=>{const b=e.target.closest('[data-object-id]');if(b)this.c.select(b.dataset.objectId);if(e.target.closest('[data-room-add]'))this.catalog();if(e.target.closest('[data-room-settings]'))this.settings();});
  $('#room-sidebar').addEventListener('keydown',e=>{const b=e.target.closest('[data-object-id]');if(b&&['Enter',' '].includes(e.key)){e.preventDefault();this.c.select(b.dataset.objectId);}});
  $('#room-walls-btn').onclick=()=>{if(!this.active)return;this.c.commit(()=>{this.data.walls={interior:'cutaway',cutaway:'none',none:'all',all:'interior'}[this.data.walls];});this.c.toast({interior:'Vista com três paredes e frente aberta.',cutaway:'Duas paredes para ver o interior.',none:'Paredes ocultas na visualização 3D.',all:'Todas as paredes visíveis.'}[this.data.walls]);};
  $('#room-entry-btn').onclick=()=>this.c.camera('entry');
  $('#room-top-btn').onclick=()=>this.c.camera('top');
  $('#room-import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw new Error('O arquivo deve ter até 5 MB.');const source=validateProject(JSON.parse(await file.text()));this.add('custom',source);}catch(err){this.c.toast(err instanceof SyntaxError?'Este arquivo não é um projeto válido.':err.message);}e.target.value='';};
 }
 activate(active){if(active&&!this.data){this.settings(true);return;}if(this.active===active)return;this.c.commit(()=>{if(this.data)this.data.active=active;this.c.setSelected(null);});this.c.onModeChange();}
 syncMode(){$('#drawing').setAttribute('aria-label',this.active?'Planta interativa do quarto. Arraste os móveis para mudar a posição. Arraste as alças para redimensionar.':'Papel quadriculado interativo. Selecione a ferramenta Linha e arraste para desenhar uma peça.');document.body.dataset.mode=this.active?'room':'furniture';document.querySelectorAll('[data-plan-mode]').forEach(b=>{b.classList.toggle('active',(b.dataset.planMode==='room')===this.active);b.setAttribute('aria-pressed',String((b.dataset.planMode==='room')===this.active));});$('#room-area-label').textContent=this.active?`${this.c.num(this.data.w*this.data.d/1e6)} m² · ${this.objects.length} ${this.objects.length===1?'móvel':'móveis'}`:'';$('#plane').disabled=this.active;$('.viewport-2d .viewport-label').innerHTML=`<i></i>${this.active?'PLANTA DO QUARTO':'DESENHO 2D'}`;if(this.lastActive!==this.active){this.lastActive=this.active;this.c.onModeChange();}}
 scene(){return roomScene(this.p);}
 renderSidebar(){const r=this.data,icon=this.c.icon;$('#room-sidebar').innerHTML=`<div class="side-section room-intro"><div class="eyebrow">PLANEJAMENTO DO AMBIENTE</div><h1>${this.c.esc(r.name)}</h1><p class="muted">Cada móvel no seu lugar.</p><button class="button full" data-room-settings>${icon('sliders')}Medidas do quarto</button><div class="room-dimension-summary"><span>Largura<strong>${this.m(r.w)}</strong></span><span>Comprimento<strong>${this.m(r.d)}</strong></span><span>Altura<strong>${this.m(r.h)}</strong></span></div></div><div class="pieces-header"><div class="section-title">Móveis <span class="count">${this.objects.length}</span></div><button class="icon-button" data-room-add title="Adicionar móvel" aria-label="Adicionar móvel">${icon('plus')}</button></div><div class="room-object-list">${this.objects.map(o=>`<button class="piece-row ${o.id===this.c.getSelected()?'selected':''}" data-object-id="${this.c.esc(o.id)}" aria-pressed="${o.id===this.c.getSelected()}"><span>${drawingIcon(CATALOG.find(v=>v.type===o.type)?.icon)}</span><span class="piece-row-name">${this.c.esc(o.name)}</span>${placementIssues(o,r).length?'<span class="placement-dot" title="Confira a posição do móvel"></span>':''}</button>`).join('')||'<p class="empty-pieces">Adicione uma cama, uma bancada ou o móvel que você está desenhando.</p>'}</div><div class="sidebar-bottom"><button class="button dark full" data-room-add>${icon('plus')}Adicionar móvel</button><p class="room-sidebar-note">Arraste as alças para dimensionar.<br><strong>R</strong> gira · <strong>Alt</strong> solta a grade.</p></div>`;}
 renderInspector(){const o=this.selected,root=$('#inspector-content'),f=this.c.field;if(!o){root.innerHTML=`<div class="empty-state room-empty">${drawingIcon('wardrobe')}<strong>Imagine seu quarto pronto.</strong><p>Adicione um móvel e arraste na planta para escolher onde ele vai ficar.</p><button class="button full" data-room-add>${this.c.icon('plus')}Adicionar móvel</button><button class="button full" data-room-settings>${this.c.icon('sliders')}Editar quarto</button></div>`;return;}root.innerHTML=`<div class="inspector-preview room-object-preview">${drawingIcon(CATALOG.find(v=>v.type===o.type)?.icon)}</div><input class="name-input" id="room-object-name" value="${this.c.esc(o.name)}" maxlength="120" aria-label="Nome do móvel"><p class="piece-kind">Móvel no quarto · ${o.type==='custom'?'seu desenho':'modelo ajustável'}</p>${o.notes?`<div class="measure-notice"><strong>${o.measurementStatus==='edited'?'Editado neste projeto':o.measurementStatus==='mixed'?'Medidas definidas + detalhes a confirmar':o.measurementStatus==='visual'?'Referência visual':'Medidas provisórias'}</strong><p>${this.c.esc(o.notes)}</p></div>`:''}${o.source?.some(p=>p.door)?`<button class="button full" data-doors-toggle>${o.doorsOpen?'Fechar portas':'Abrir portas'}</button>`:''}<div class="property-heading">Dimensões <span>${this.p.unit==='cm'?'centímetros':'milímetros'}</span></div><div class="property-grid">${f('Largura','w',o.w,1,20000)}${f('Altura','h',o.h,1,20000)}${f('Profundidade','d',o.d,1,20000)}</div><div class="property-heading">Posição no quarto</div><div class="property-grid">${f('X · horizontal','x',o.x)}${f('Z · comprimento','z',o.z)}${f('Y · altura do piso','y',o.y)}</div><div class="property-heading">Orientação <span>em torno do centro</span></div><div class="rotation-row">${f('Giro','rotation',o.rotation,-360,360,'°')}<button class="button" data-room-rotate>Girar 90°</button></div><div class="property-heading">Acabamento</div><div class="materials">${Object.entries(MATERIALS).map(([key,m])=>`<button class="swatch ${o.material===key?'active':''}" data-room-material="${key}" style="background:${m.color}" aria-label="${m.name}" title="${m.name}"></button>`).join('')}</div>${o.type==='custom'?'<button class="original-material" data-original-material>Usar cores do desenho original</button>':''}<div class="placement-status" id="placement-status"></div><div class="piece-actions"><button class="button" data-room-duplicate>${this.c.icon('copy')}Duplicar</button><button class="button danger" data-room-delete aria-label="Excluir móvel">${this.c.icon('trash')}</button></div><p class="piece-footnote">O giro e a posição alteram o móvel inteiro. Seu desenho de marcenaria continua disponível na aba Móvel.</p>`;this.updateIssues();}
 updateIssues(){const node=$('#placement-status'),o=this.selected;if(!node||!o)return;const issues=placementIssues(o,this.data);node.classList.toggle('has-issue',Boolean(issues.length));node.textContent=issues.length?issues.join(' · '):'Dentro dos limites do quarto';}
 changeInspector(e){const o=this.selected;if(!o)return;if(e.target.id==='room-object-name'){const name=e.target.value.trim();if(name)this.c.commit(()=>o.name=name,{keepInspector:true});return;}const key=e.target.dataset.prop;if(!key)return;const raw=Number(e.target.value);if(e.target.value===''||!Number.isFinite(raw)||raw<Number(e.target.min)||raw>Number(e.target.max)){this.c.toast('Confira os limites dessa medida.');this.renderInspector();return;}const value=this.c.inputValue(e.target);this.c.commit(()=>{o[key]=value;o.measurementStatus='edited';},{keepInspector:true});this.updateIssues();}
 clickInspector(e){if(e.target.closest('[data-doors-toggle]')&&this.selected)this.c.commit(()=>this.selected.doorsOpen=!this.selected.doorsOpen);if(e.target.closest('[data-room-add]'))this.catalog();if(e.target.closest('[data-room-settings]'))this.settings();if(e.target.closest('[data-room-rotate]'))this.rotateSelected();if(e.target.closest('[data-room-duplicate]'))this.duplicate();if(e.target.closest('[data-room-delete]'))this.remove();const m=e.target.closest('[data-room-material]');if(m&&this.selected)this.c.commit(()=>this.selected.material=m.dataset.roomMaterial);if(e.target.closest('[data-original-material]')&&this.selected)this.c.commit(()=>this.selected.material=null);}
 rotateSelected(){if(!this.selected){this.c.toast('Selecione um móvel para girar.');return;}this.c.commit(()=>this.selected.rotation=(this.selected.rotation+90)%360);}
 duplicate(){if(this.objects.length>=150){this.c.toast('Este quarto já tem 150 móveis.');return;}const o=this.selected;if(!o)return;this.c.commit(()=>{const copy=clone(o);copy.id=uid();copy.name+=' (cópia)';const pos=findPlacement(copy,this.data);Object.assign(copy,pos);this.objects.push(copy);this.c.setSelected(copy.id);});}
 remove(){const o=this.selected;if(!o)return;this.c.commit(()=>{this.data.objects=this.objects.filter(v=>v.id!==o.id);this.c.setSelected(null);});}
 add(type,source){if(this.objects.length>=150){this.c.toast('Este quarto já tem 150 móveis.');return;}try{const object=createRoomObject(type,source||this.p);Object.assign(object,findPlacement(object,this.data));this.c.commit(()=>{this.objects.push(object);this.c.setSelected(object.id);});$('#modal').close();this.c.toast('Móvel adicionado. Arraste na planta ou ajuste a posição.');}catch(e){this.c.toast(e.message);}}
 catalog(){this.c.modal('O que vai no seu quarto?',`<p>Escolha um modelo e ajuste as medidas para o seu móvel.</p><div class="furniture-catalog">${CATALOG.map(item=>`<button class="catalog-card" data-catalog-type="${item.type}">${drawingIcon(item.icon)}<strong>${item.name}</strong><small>${this.m(item.w)} × ${this.m(item.d)}</small></button>`).join('')}</div><button class="catalog-own" id="add-current-model">${this.c.icon('layers')}<span><strong>Colocar o móvel que estou desenhando</strong><small>${this.c.esc(this.p.name)} · ${this.p.pieces.length} peças</small></span><b>+</b></button><button class="button full" id="import-room-object">${this.c.icon('upload')}Carregar outro móvel salvo (JSON)</button>`,`<button class="button" data-close>Fechar</button>`);$('#modal-content').querySelectorAll('[data-catalog-type]').forEach(b=>b.onclick=()=>this.add(b.dataset.catalogType));$('#add-current-model').onclick=()=>this.add('custom');$('#import-room-object').onclick=()=>$('#room-import-file').click();}
 settings(creating=false){const r=clone(this.data||createRoom()),f=this.c.field,opening=(type,label)=>{const o=r[type]||{wall:type==='door'?'front':'back',offset:100,width:800,height:type==='door'?2100:1000,bottom:type==='door'?0:1000};return `<details class="opening-settings"><summary>${label}</summary><label class="opening-toggle"><input id="${type}-enabled" type="checkbox" ${r[type]?'checked':''}>Incluir ${label.toLowerCase()}</label><label class="form-field"><span>Parede</span><select id="${type}-wall">${[['back','Fundo'],['front','Frente'],['left','Esquerda'],['right','Direita']].map(([key,name])=>`<option value="${key}" ${o.wall===key?'selected':''}>${name}</option>`).join('')}</select></label><div class="property-grid room-form-grid">${f('Distância do canto',type+'-offset',o.offset,0,20000)}${f('Largura',type+'-width',o.width,100,20000)}${f('Altura',type+'-height',o.height,100,20000)}${type==='window'?f('Altura do peitoril',type+'-bottom',o.bottom,0,20000):''}</div></details>`;};this.c.modal(creating?'Crie seu quarto.':'Medidas do quarto',`<div class="room-settings-scroll"><label class="form-field"><span>Nome do ambiente</span><input id="room-name" class="text-input" maxlength="120" value="${this.c.esc(r.name)}"></label><div class="property-grid room-form-grid">${f('Largura do quarto','room-w',r.w,500,20000)}${f('Comprimento do quarto','room-d',r.d,500,20000)}${f('Altura do quarto','room-h',r.h,500,20000)}</div><p class="room-form-help">Medidas internas entre paredes. ${this.p.unit==='cm'?'100 cm':'1.000 mm'} = 1 metro. Você pode ajustar tudo depois.</p><div class="room-color-fields"><label>Paredes<input type="color" id="wall-color" value="${r.wallColor}"></label><label>Piso<input type="color" id="floor-color" value="${r.floorColor}"></label></div>${opening('door','Porta')}${opening('window','Janela')}${creating&&this.p.pieces.length?'<label class="opening-toggle include-current"><input type="checkbox" id="include-current-model">Colocar também o móvel que estou desenhando</label>':''}</div>`,`<button class="button" data-close>Cancelar</button><button class="button dark" id="confirm-room">${creating?'Criar quarto':'Salvar quarto'}</button>`);const openingEdited={door:false,window:false};$('.room-settings-scroll').addEventListener('input',e=>{for(const type of ['door','window'])if(e.target.dataset.prop?.startsWith(type+'-')||e.target.id?.startsWith(type+'-'))openingEdited[type]=true;});$('#confirm-room').onclick=()=>{try{const get=key=>this.c.inputValue($(`[data-prop="${key}"]`));for(const key of ['w','d','h'])r[key]=get('room-'+key);r.name=$('#room-name').value.trim()||'Meu quarto';r.wallColor=$('#wall-color').value;r.floorColor=$('#floor-color').value;r.active=true;for(const type of ['door','window'])r[type]=$('#'+type+'-enabled').checked?{measurementStatus:openingEdited[type]?'edited':r[type]?.measurementStatus||'provisional',wall:$('#'+type+'-wall').value,offset:get(type+'-offset'),width:get(type+'-width'),height:get(type+'-height'),bottom:type==='window'?get(type+'-bottom'):0}:null;for(const type of ['door','window']){const o=r[type];if(o&&!openingEdited[type]){const length=['back','front'].includes(o.wall)?r.w:r.d;o.width=Math.min(o.width,length-100);o.offset=Math.max(0,Math.min(o.offset,length-o.width));o.height=Math.min(o.height,r.h-100);o.bottom=Math.max(0,Math.min(o.bottom,r.h-o.height));}}validateRoomCopy(r);if(creating&&$('#include-current-model')?.checked){const o=createRoomObject('custom',this.p);Object.assign(o,findPlacement(o,r));r.objects.push(o);}this.c.commit(()=>{this.p.room=r;this.c.setSelected(null);});$('#modal').close();this.c.onModeChange();this.c.toast('Quarto pronto. Adicione os móveis e escolha as posições.');}catch(e){this.c.toast(e.message);}};}
 hitTest(point,toScreen){for(const o of [...this.objects].reverse()){const poly=footprint(o).map(toScreen);let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a.y>point.y)!==(b.y>point.y)&&point.x<(b.x-a.x)*(point.y-a.y)/(b.y-a.y)+a.x)hit=!hit;}if(hit)return o;}return null;}
 draw(ctx,{toScreen,dimension,label,scale}){const r=this.data,A=toScreen({u:0,v:0}),B=toScreen({u:r.w,v:r.d});ctx.fillStyle=r.floorColor+'22';ctx.fillRect(A.x,B.y,B.x-A.x,A.y-B.y);const wallPoint=(wall,t)=>wall==='back'?{u:t,v:0}:wall==='front'?{u:t,v:r.d}:wall==='left'?{u:0,v:t}:{u:r.w,v:t};
  for(const wall of ['back','front','left','right']){const length=['back','front'].includes(wall)?r.w:r.d,P=toScreen(wallPoint(wall,0)),Q=toScreen(wallPoint(wall,length));ctx.lineWidth=6;ctx.strokeStyle='#7c886c';ctx.beginPath();ctx.moveTo(P.x,P.y);ctx.lineTo(Q.x,Q.y);ctx.stroke();for(const type of ['door','window']){const o=r[type];if(!o||o.wall!==wall)continue;const p=toScreen(wallPoint(wall,o.offset)),q=toScreen(wallPoint(wall,o.offset+o.width));ctx.strokeStyle='#fafbf6';ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();ctx.lineWidth=type==='window'?3:1;ctx.strokeStyle=type==='window'?'#8caab0':'#b09b75';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();if(type==='door'){const radius=o.width*scale,angle=Math.atan2(q.y-p.y,q.x-p.x),delta=['back','right'].includes(wall)?-Math.PI/2:Math.PI/2;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+Math.cos(angle+delta)*radius,p.y+Math.sin(angle+delta)*radius);ctx.moveTo(q.x,q.y);ctx.arc(p.x,p.y,radius,angle,angle+delta,delta<0);ctx.stroke();}}}
  for(const o of this.objects){const poly=footprint(o).map(toScreen),isSelected=o.id===this.c.getSelected(),issues=placementIssues(o,r);ctx.beginPath();poly.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=isSelected?'#dce9c5':MATERIALS[o.material||'oak'].color+'b8';ctx.fill();ctx.strokeStyle=isSelected?'#5d803f':issues.length?'#b08a60':'#9d997b';ctx.lineWidth=isSelected?1.8:1;ctx.stroke();if(['bed','double-bed'].includes(o.type)){const c={x:poly.reduce((s,p)=>s+p.x,0)/4,y:poly.reduce((s,p)=>s+p.y,0)/4};ctx.save();ctx.translate(c.x,c.y);ctx.rotate(o.rotation*Math.PI/180);ctx.fillStyle='#fff9';ctx.fillRect(-o.w*scale*.37,o.d*scale*.24,o.w*scale*.74,o.d*scale*.18);ctx.restore();}const center=toScreen({u:o.x+o.w/2,v:o.z+o.d/2});ctx.save();ctx.font='500 9px "DM Sans",system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#5e6e51';const max=Math.max(o.w,o.d)*scale;let name=o.name;while(ctx.measureText(name).width>max-12&&name.length>4)name=name.slice(0,-2)+'…';if(Math.min(o.w,o.d)*scale>9){if(o.d>o.w*3){ctx.translate(center.x,center.y);ctx.rotate(-Math.PI/2);ctx.fillText(name,0,0);}else ctx.fillText(name,center.x,center.y);}ctx.restore();if(isSelected){dimension(footprint(o)[0],footprint(o)[1],this.m(o.w),-19);dimension(footprint(o)[1],footprint(o)[2],this.m(o.d),-19);}}
  const front=toScreen({u:r.w/2,v:r.d});label('ENTRADA',front.x,front.y-18,'#7d866f');dimension({u:0,v:0},{u:r.w,v:0},this.m(r.w),30);dimension({u:0,v:0},{u:0,v:r.d},this.m(r.d),-30);if(!this.objects.length){const center=toScreen({u:r.w/2,v:r.d/2});label('Adicione seu primeiro móvel',center.x,center.y,'#8b9b78','#f9faf3');}
 }
}
